  gap: 0.25rem;
  border-bottom: 2px solid var(--border);
}

.tab-bar label {
  padding: 0.6rem 1.1rem;
  cursor: pointer;
  border-radius: 8px 8px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
  user-select: none;
}

