}

#tab-chart:checked ~ #panel-chart,
#tab-aspects:checked ~ #panel-aspects,
#tab-jaimini:checked ~ #panel-jaimini,
#tab-panchanga:checked ~ #panel-panchanga,
#tab-compat:checked ~ #panel-compat,
#tab-ask:checked ~ #panel-ask {
  display: flex;
}

/* ---- Chart tab: Rasi/Dasha/Navamsa on the left, Planets on the right ---- */

.chart-tab-grid {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) minmax(320px, 1.4fr);
  gap: 1.5rem;
  align-items: start;
}

.chart-tab-left,
.chart-tab-right {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

@media (max-width: 900px) {
