def test_compute_match_report_identical_charts_score_full_except_nadi() -> None:
    # Matching a chart against itself scores full marks on every koota except
    # Nadi: identical nakshatra necessarily means identical Nadi group, which
    # is exactly what Nadi Dosha flags (0/8) - a real, correct quirk of the
    # system, not a bug (astrological "twins" are a classic Nadi Dosha case).
    chart = _bride_chart()
    report = compute_match_report(chart, chart)
    by_name = {k.name: k for k in report.kootas}
    assert by_name["Nadi"].points_earned == 0
    for name, koota in by_name.items():
        if name != "Nadi":
            assert koota.points_earned == koota.max_points, name
    assert report.total_points == 28.0

